#!/usr/bin/env python3
"""Production scroll owner: cold section cadence, barrier hold, clear bonus and timeout."""
from pathlib import Path
import hashlib,json,re,subprocess
r=Path(__file__).resolve().parents[1];o=r/'out/parity-audit/section-stop-integration';o.mkdir(parents=True,exist_ok=True)
syms={n:int(v,16)&0xffffff for v,n in re.findall(r'^([0-9a-fA-F]+)\s+\w\s+(\w+)\s*$',(r/'out/symbol.txt').read_text(),re.M)}
rh=hashlib.sha256((r/'out/rom.bin').read_bytes()).hexdigest()
s='local cpu=manager.machine.devices[":maincpu"];local m=cpu.spaces.program\nlocal frame=0;local updates=0;local checks=0;local terminal=false;local phase=0;local held=0;local pending=false\nlocal function clear(a,n)for k=0,n-1 do m:write_u8(a+k,0)end end\nlocal function check(v,why)checks=checks+1;assert(v,why..\' update \'..updates)end\nlocal function invoke()\n for x=0xffb000,0xffb03e,2 do m:write_u16(x,0x4e71)end\n m:write_u16(0xffb040,0x4eb9);m:write_u32(0xffb042,FN);m:write_u16(0xffb046,0x60fe)\n cpu.state[\'SR\'].value=0x2700;cpu.state[\'SP\'].value=0xffbfe0;cpu.state[\'PC\'].value=0xffb000;pending=true\nend\nlocal function finish(err)\n terminal=true;local f=assert(io.open(RESULT,\'w\'));f:write(string.format(\'{"updates":%d,"checks":%d,"error":%s}\',updates,checks,err and string.format(\'%q\',err)or\'null\'));f:close();manager.machine:exit()\nend\nemu.register_frame_done(function()\n if terminal then return end;frame=frame+1;if frame<60 then return end\n local ok,err=pcall(function()\n if not pending then\n  clear(GG,94);clear(SECTION,12);clear(FOOD,202);clear(SPAWN,4);clear(PICKUP,16)\n  m:write_u8(SURVIVAL,0);m:write_u16(SUB,0);m:write_u8(LATCH,8);m:write_u8(ADVANCE,0);m:write_u8(GRADE,0);m:write_u16(DIFFICULTY,0)\n  m:write_u8(SECTION+5,4)\n  -- The real first barrier stays active throughout this scroll-owner fixture.\n  m:write_u16(FOOD,3968);m:write_u8(FOOD+4,3);m:write_u8(FOOD+9,2)\n else\n  updates=updates+1;check(cpu.state[\'CURPC\'].value&0xffffff==0xffb046,\'return\')\n  local camera=m:read_u16(GG+88);local stop=m:read_u8(SECTION+8)\n  if phase==0 then\n   if stop==1 then\n    check(camera==3840,\'first stop position\');check(m:read_u8(SECTION+4)==4,\'next section\');check(m:read_u8(SECTION+10)==20,\'timer\');check(m:read_u8(ADVANCE)==1,\'entry signal\');check(m:read_u16(DIFFICULTY)==1024,\'difficulty\');phase=1\n   else check(camera<3840,\'stop not skipped\')end\n  elseif phase==1 then\n   check(camera==3840 and stop==1,\'barrier hold\');check(m:read_u8(ADVANCE)==1,\'retained signal\');held=held+1\n   if held==4 then m:write_u8(FOOD+4,0);phase=2 end\n  elseif phase==2 then\n   check(camera==3840 and stop==0,\'clear release\');check(m:read_u8(GRADE)==1,\'grade increment\');check(m:read_u8(SPAWN)==1 and m:read_u8(SPAWN+1)==0 and m:read_u8(SPAWN+2)==104,\'bonus request\');check(m:read_u8(PICKUP+6)==10,\'bonus kind\')\n   clear(SPAWN,4);m:write_u8(SECTION+8,1);m:write_u8(SECTION+10,1);m:write_u8(FOOD+4,3);phase=3\n  elseif phase==3 then\n   check(camera==3840 and stop==0,\'timeout release\');check(m:read_u8(GRADE)==1 and m:read_u8(SPAWN)==0,\'timeout no reward\');phase=4\n  else\n   check(camera>=3840 and stop==0,\'resume\');finish();return\n  end\n end\n m:write_u8(CLOCK,phase==3 and 0 or 1)\n invoke()\n end)\n if not ok then finish(err)end\n if frame>7600 and not terminal then finish(\'timeout\')end\nend)\n'
for k,v in {'GG':syms['g_game'],'SECTION':syms['g_arcadeSection'],'FOOD':syms['pool'],'SPAWN':syms['arcade_food_spawn'],'PICKUP':syms['arcade_food_pickup'],'SURVIVAL':syms['g_survivalRun'],'SUB':syms['g_scrollSub'],'LATCH':syms['g_scrollColumnLatch'],'ADVANCE':syms['g_scrollColumnAdvance'],'GRADE':syms['g_sectionGrade'],'DIFFICULTY':syms['g_arcadeCombatDifficulty'],'CLOCK':syms['wave_clock'],'FN':syms['game_arcade_scroll_tick'],'RESULT':json.dumps(str(o/'results.json'))}.items():s=re.sub(r'\b'+k+r'\b',str(v),s)
(o/'run.lua').write_text(s)
subprocess.run(['mame','genesis','-cart',str(r/'out/rom.bin'),'-window','-nomaximize','-resolution','512x448','-video','none','-keyboardprovider','none','-mouseprovider','none','-joystickprovider','none','-noreadconfig','-sound','none','-nothrottle','-skip_gameinfo','-autoboot_script',str(o/'run.lua'),'-cfg_directory',str(o/'cfg'),'-nvram_directory',str(o/'nvram')],cwd=r,stdout=(o/'mame.log').open('w'),stderr=subprocess.STDOUT,timeout=120,check=True)
assert hashlib.sha256((r/'out/rom.bin').read_bytes()).hexdigest()==rh
result=json.loads((o/'results.json').read_text());result['rom_sha256']=rh;(o/'results.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2));assert result['error']is None and result['updates']>6900,result
